import { execFileSync } from 'node:child_process';
const EXE = '/workspace/dataset/test19_executable';
const MK = { a:'MKAA', b:'MKBB', c:'MKCC', d:'MKDD', e:'MKEE', f:'MKFF' };
const ORDER = ['a','b','c','d','e','f'];

export function raw(args){
  const argv=[];
  for(const k of ORDER) argv.push('--'+k, args[k]===undefined?MK[k]:args[k]);
  try { return execFileSync(EXE, argv, {encoding:'utf8', maxBuffer:1<<28}); }
  catch(e){ return 'ERR('+e.status+')\n'+(e.stdout||'')+(e.stderr||''); }
}

// Batch: cases = array of strings. Returns {e:[...], p5:[...]}
export function batch(cases){
  const sep = (i)=>'ZQMARK'+i+'ZQ';
  const parts=[];
  cases.forEach((c,i)=>{ parts.push(sep(i)); parts.push(c); });
  parts.push(sep(cases.length));
  const text = parts.join('\n\n');
  const out = raw({e:text});
  const lines = out.split('\n');
  // phase2_e : between <p>MKDD</p> and <p>MKFF</p>
  const s1 = lines.indexOf('<p>MKDD</p>')+1;
  const e1 = lines.indexOf('<p>MKFF</p>', s1);
  const eBlock = lines.slice(s1,e1).join('\n');
  // phase5: tail after last </article>
  let i = lines.length-1; while(i>=0 && lines[i]==='') i--;
  let j=i; while(j>=0 && !lines[j].includes('</article>')) j--;
  const tail = lines.slice(j+1, i+1);
  const s2 = tail.lastIndexOf('<p>MKDD</p>')+1;
  const e2 = tail.lastIndexOf('<p>MKFF</p>');
  const p5Block = tail.slice(s2,e2).join('\n');
  return { e: split(eBlock, cases.length), p5: split(p5Block, cases.length), rawE:eBlock, rawP5:p5Block };
}

function split(block, n){
  const res=[];
  for(let i=0;i<n;i++){
    const a='<p>ZQMARK'+i+'ZQ</p>';
    const b='<p>ZQMARK'+(i+1)+'ZQ</p>';
    const ia=block.indexOf(a); const ib=block.indexOf(b, ia<0?0:ia);
    if(ia<0||ib<0){ res.push({ERROR:'split-fail', a, ia, ib}); continue; }
    res.push(block.slice(ia+a.length, ib).replace(/^\n+/,'').replace(/\n+$/,''));
  }
  return res;
}

// single-case, no batching
export function one(s){
  const out = raw({e:s});
  const lines = out.split('\n');
  const s1 = lines.indexOf('<p>MKDD</p>')+1;
  const e1 = lines.indexOf('<p>MKFF</p>', s1);
  const eBlock = lines.slice(s1,e1).join('\n');
  let i = lines.length-1; while(i>=0 && lines[i]==='') i--;
  let j=i; while(j>=0 && !lines[j].includes('</article>')) j--;
  const tail = lines.slice(j+1, i+1);
  const s2 = tail.lastIndexOf('<p>MKDD</p>')+1;
  const e2 = tail.lastIndexOf('<p>MKFF</p>');
  return { e: eBlock, p5: tail.slice(s2,e2).join('\n') };
}
