for(let s=0;s<LANGS.length;s+=N){
  const chunk = LANGS.slice(s,s+N);
  const cases = chunk.map(l=>'```'+l+'\n'+SNIP[l]+'\n```');
  const b = batch(cases);
  chunk.forEach((l,i)=>{ res[l]={lang:b.e[i]}; });
}
